// classes/ItemFactory.ts
class ItemFactory {
  static async createItem(itemId) {
    let itemModule;
    switch (itemId) {
      case "ak47":
        itemModule = await Promise.resolve().then(() => (init_AK47Entity(), exports_AK47Entity));
        break;
      case "auto-shotgun":
        itemModule = await Promise.resolve().then(() => (init_AutoShotgunEntity(), exports_AutoShotgunEntity));
        break;
      case "auto-sniper":
        itemModule = await Promise.resolve().then(() => (init_AutoSniperEntity(), exports_AutoSniperEntity));
        break;
      case "bolt-action-sniper":
        itemModule = await Promise.resolve().then(() => (init_BoltActionSniperEntity(), exports_BoltActionSniperEntity));
        break;
      case "gravity-potion":
        itemModule = await Promise.resolve().then(() => (init_GravityPotionEntity(), exports_GravityPotionEntity));
        break;
      case "light-machine-gun":
        itemModule = await Promise.resolve().then(() => (init_LightMachineGunEntity(), exports_LightMachineGunEntity));
        break;
      case "medpack":
        itemModule = await Promise.resolve().then(() => (init_MedPackEntity(), exports_MedPackEntity));
        break;
      case "mining-drill":
        itemModule = await Promise.resolve().then(() => (init_MiningDrillEntity(), exports_MiningDrillEntity));
        break;
      case "pistol":
        itemModule = await Promise.resolve().then(() => (init_PistolEntity(), exports_PistolEntity));
        break;
      case "revolver":
        itemModule = await Promise.resolve().then(() => (init_RevolverEntity(), exports_RevolverEntity));
        break;
      case "rocket-launcher":
        itemModule = await Promise.resolve().then(() => (init_RocketLauncherEntity(), exports_RocketLauncherEntity));
        break;
      case "submachine-gun":
        itemModule = await Promise.resolve().then(() => (init_SubmachineGunEntity(), exports_SubmachineGunEntity));
        break;
      case "shotgun":
        itemModule = await Promise.resolve().then(() => (init_ShotgunEntity(), exports_ShotgunEntity));
        break;
      case "shield-potion":
        itemModule = await Promise.resolve().then(() => (init_ShieldPotionEntity(), exports_ShieldPotionEntity));
        break;
      default:
        throw new Error(`Unknown chest item id: ${itemId}`);
    }
    const itemClass = itemModule.default;
    const item = new itemClass;
    return item;
  }
}

